{
  "story": "Tokens enter the transformer, converting text into dense continuous vectors. Positional encoding adds sequence order. Self-attention weights contextual relationships across all words simultaneously, producing final enriched embeddings for downstream tasks.",
  "aha": {
    "stateId": "step-attention",
    "observation": "Self-attention computes dot products between queries and keys, routing information dynamically between unrelated words based on context."
  },
  "layout": {
    "preset": "stepper-card",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "picture",
      "kind": "fixed-picture",
      "bind": {
        "active": "inputs.stepIndex",
        "regions": "variant.regions",
        "values": "state.readouts"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "readout",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Transformer Stage",
      "options": [
        "Tokenization",
        "Embedding",
        "Positional Encoding",
        "Self-Attention",
        "Final Vector"
      ]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset"
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Detailed Embedding Pipeline",
        "regions": [
          {
            "id": "reg-tokens",
            "label": "Input Tokens",
            "kind": "array",
            "values": ["The", "bank", "of", "river"]
          },
          {
            "id": "reg-vectors",
            "label": "Embedding Table",
            "kind": "matrix",
            "values": ["0.25", "-0.11", "0.84", "0.42"]
          },
          {
            "id": "reg-pos",
            "label": "Positional Signal",
            "kind": "vector",
            "values": ["0.01", "1.00", "0.99", "0.00"]
          },
          {
            "id": "reg-attention",
            "label": "Attention Matrix",
            "kind": "matrix",
            "values": ["0.1", "0.8", "0.0", "0.1"]
          }
        ],
        "states": [
          {
            "id": "step-tokens",
            "label": "Tokenize",
            "short": "Split",
            "sentence": "The raw sentence is split into discrete subword tokens.",
            "why": "Mapping words to integer IDs prepares text for numerical lookup.",
            "active": ["reg-tokens"],
            "calloutRegion": "reg-tokens",
            "readouts": [
              {
                "id": "vocab",
                "label": "Vocab Size",
                "value": "32000"
              }
            ]
          },
          {
            "id": "step-embed",
            "label": "Embed",
            "short": "Lookup",
            "sentence": "Each token ID fetches a high-dimensional vector from the embedding table.",
            "why": "Converts discrete symbols into continuous semantic space.",
            "active": ["reg-vectors"],
            "calloutRegion": "reg-vectors",
            "readouts": [
              {
                "id": "dim",
                "label": "Hidden Dim",
                "value": "768"
              }
            ]
          },
          {
            "id": "step-pos",
            "label": "Position",
            "short": "Inject",
            "sentence": "Sinusoidal positional encodings are added to retain word order.",
            "why": "Transformers process sets, so explicit position prevents loss of syntax.",
            "active": ["reg-pos"],
            "calloutRegion": "reg-pos",
            "readouts": [
              {
                "id": "max-len",
                "label": "Max Length",
                "value": "2048"
              }
            ]
          },
          {
            "id": "step-attention",
            "label": "Attention",
            "short": "Context",
            "sentence": "Queries, keys, and values compute weighted sums across all token vectors.",
            "why": "Resolves polysemy by blending contextual semantics into each vector.",
            "active": ["reg-attention"],
            "calloutRegion": "reg-attention",
            "readouts": [
              {
                "id": "heads",
                "label": "Attention Heads",
                "value": "12"
              }
            ]
          },
          {
            "id": "step-final",
            "label": "Output",
            "short": "Vector",
            "sentence": "The resulting context-aware vectors emerge as final embeddings.",
            "why": "Ready for classification, generation, or retrieval tasks.",
            "active": ["reg-tokens", "reg-vectors", "reg-attention"],
            "calloutRegion": "reg-vectors",
            "readouts": [
              {
                "id": "norm",
                "label": "Vector Norm",
                "value": "1.00"
              }
            ]
          }
        ]
      }
    ]
  }
}
